// ———— 保险丝 2：Token 预算 ————

const TOKEN_BUDGET = 15000;
let totalOutput = 0;
let lowStreak = 0;

function checkBudget(tokens: number): 'ok' | 'nudge' | 'stop' {
  totalOutput += tokens;

  // 递减回报：连续 2 次增量 < 500 → 停止
  if (tokens < 500) {
    lowStreak++;
  } else {
    lowStreak = 0;
  }
  if (lowStreak >= 2) return 'stop';

  // 90% 预算 → 注入 nudge
  if (totalOutput >= TOKEN_BUDGET * 0.9) return 'nudge';
  return 'ok';
}

// ———— Agent Loop ————

setScenario('token_burn');
