    if (cmd !== 'status' && cmd !== '查��状态') return false;
    const tokens = estimateMessageTokens(ctx.messages);
    const memCount = ctx.memoryStore?.list().length ?? 0;
    const ragCount = ctx.vectorStore?.size() ?? 0;
